    const status = document.getElementById("quiz-status");

    const questionNames = {
      q1: "Question 1",
      q2: "Question 2",
      q3: "Question 3"
    };

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      let correctCount = 0;
      const missedQuestions = [];

      for (const [name, correctValues] of Object.entries(answers)) {
        const selectedValues = [...form.querySelectorAll(`input[name="${name}"]:checked`)].map((input) => input.value);
        const selectionSet = new Set(selectedValues);
        const correctSet = new Set(correctValues);

        const isExactMatch =
          selectedValues.length === correctValues.length &&
          selectedValues.every((value) => correctSet.has(value));

        if (isExactMatch) {
          correctCount += 1;
        } else {
          missedQuestions.push(questionNames[name]);
        }

