          card.style.background = isExactMatch ? "rgba(15, 138, 95, 0.08)" : "";
        });
      }

      const total = Object.keys(answers).length;
      const missedText = missedQuestions.length
        ? ` Review ${missedQuestions.join(", ")}.`
        : "";

